        cookies_alice = requests.utils.dict_from_cookiejar(cookies_alice_jar)
        
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.body.unexpected No response body is expected but one was found.
        headers = {}
        headers['Accept'] = "*/*"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/json/status",
                    headers=headers, cookies=cookies_alice, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 403
        assert "text/html" in res_0.headers["content-type"]


